def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    danger_count = 0
    rich_count = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if float(opp.get('hp', 0)) <= 4 or int(opp.get('no_water_days', 0)) >= 1:
                danger_count += 1
            if float(opp.get('budget', 0)) >= budget:
                rich_count += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))

    if not alive:
        return round(min(budget, 8.0), 2)

    max_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 3:
        urgency += 0.55
    elif hp <= 5:
        urgency += 0.3
    if no_water >= 2:
        urgency += 0.5
    elif no_water >= 1:
        urgency += 0.22
    if day >= 8:
        urgency += 0.08

    pressure = 0.18 + 0.42 * scarcity + 0.28 * urgency
    if danger_count >= 2:
        pressure += 0.06
    if rich_count >= 2:
        pressure += 0.04

    target = DAILY_SALARY * pressure

    if max_prev > 0:
        if scarcity >= 0.7 or urgency >= 0.45:
            target = max(target, min(max_prev + 2.0, DAILY_SALARY * 1.12))
        elif max_prev >= 120:
            target = min(target, avg_prev * 0.72)
        else:
            target = max(target, avg_prev * 0.88)

    if supply >= 22 and urgency < 0.3:
        target *= 0.75
    elif supply <= 17:
        target *= 1.18

    if hp <= 2 or no_water >= 2:
        target = max(target, DAILY_SALARY * 0.95)

    reserve_floor = 0.0
    days_left = max(0, 10 - day)
    if days_left > 0:
        reserve_floor = min(budget * 0.35, days_left * 10.0)
    cap = max(0.0, budget - reserve_floor)
    if hp <= 3 or no_water >= 2:
        cap = budget

    bid = min(target, cap if cap > 0 else budget)
    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    if bid == 0.0 and (hp <= 3 or no_water >= 1):
        bid = min(budget, DAILY_SALARY * 0.55)

    return round(bid, 2)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.4)

    base_bid = DAILY_SALARY * 0.9

    # Adjust bid based on my HP
    HP_CRITICAL_THRESHOLD = 3
    HP_LOW_THRESHOLD = 5

    if my_hp <= HP_CRITICAL_THRESHOLD:
        base_bid = DAILY_SALARY * 1.15
    elif my_hp <= HP_LOW_THRESHOLD:
        base_bid = DAILY_SALARY * 1.05

    # Adjust bid based on opponent's previous day bids
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        max_yesterday_bid = max(yesterday_bids)
        if max_yesterday_bid >= DAILY_SALARY * 0.9:
            base_bid = max(base_bid, max_yesterday_bid + 5.0)
        elif max_yesterday_bid >= DAILY_SALARY * 0.7:
            base_bid = max(base_bid, max_yesterday_bid + 2.0)
        else:
            base_bid = min(base_bid, max_yesterday_bid + 10.0)

    # Adjust bid based on current supply
    if current_supply <= WATER_REQ + 2:
        base_bid = max(base_bid, DAILY_SALARY * 1.05)
    elif current_supply >= WATER_REQ * 1.5:
        base_bid = min(base_bid, DAILY_SALARY * 0.8)

    # Final constraints
    bid_amount = min(base_bid, my_budget)

    if bid_amount <= 0.0 and my_budget > 0.0:
        bid_amount = 1.0
    elif bid_amount <= 0.0:
        bid_amount = 0.0

    return bid_amount

